    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            if key is None:
                cache_key = (args, tuple(sorted(kwargs.items())))
            else:
                cache_key = key(*args, **kwargs)
            if cache_key not in cache:
                if lock is not None:
                    with lock:
                        cache[cache_key] = func(*args, **kwargs)
