def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number == 0:
        return alphabet[0]

    num_digits = len(alphabet)
    result = []

    while number > 0:
        remainder = number % num_digits
        result.append(alphabet[remainder])
        number = number // num_digits

