    graph_data = []
    for bin_ in hist.bins:
        coordinates = (bin_.x_min, bin_.x_max)
        value = make_value(bin_)
        if isinstance(value, tuple):
            value = value + coordinates_func(coordinates),
        else:
            value = (value, coordinates_func(coordinates))
        graph_data.append(value)

    graph = {
        "data": graph_data,
        "field_names": field_names
    }

    if scale is True:
        graph["scale"] = hist.scale

